package br.com.tapeteskalke.controller; import br.com.tapeteskalke.dto.ApiResponse; import br.com.tapeteskalke.service.CodigoService; import br.com.tapeteskalke.service.CodigoService.Tabela; import java.util.*; import org.springframework.web.bind.annotation.*;
// Listas de códigos para os selects do front (qualquer usuário autenticado).
@RestController @RequestMapping("/api/v1/codigos") public class CodigoController { private final CodigoService codigos; public CodigoController(CodigoService codigos){this.codigos=codigos;} @GetMapping public ApiResponse<Map<String,List<Map<String,Object>>>> all(){var m=new LinkedHashMap<String,List<Map<String,Object>>>();m.put("formasPagamento",codigos.list(Tabela.FORMA_PAGAMENTO));m.put("tiposProduto",codigos.list(Tabela.TIPO_PRODUTO));m.put("unidadesMedida",codigos.list(Tabela.UNIDADE_MEDIDA));m.put("tiposDespesa",codigos.list(Tabela.TIPO_DESPESA));return ApiResponse.ok(m);} }
